/** Atomic counter for generating sequential document numbers (SA-0001, etc.) */
export const sequences = sqliteTable('sequences', {
  /** Unique sequence identifier — 'sale', 'invoice', 'quote', etc. */
  name: text('name').primaryKey(),
  /** Current counter value — starts at 0, incremented atomically on each use */
  currentValue: integer('current_value', { mode: 'number' }).notNull().default(0),
})

export type Sequence = typeof sequences.$inferSelect
export type NewSequence = typeof sequences.$inferInsert

